import re

import pytest


def title_of(html: str) -> str:
    """Return the text between the first `<title>` and the next `</title>`.

    Tag names are matched case-insensitively (`<TITLE>` works). The text
    is returned exactly as it appears, with no stripping or entity
    decoding. Returns "" if there is no `<title>` tag, if it is never
    closed, or if the title is empty. Does no network access.
    """
    match = re.search(r"<title>(.*?)</title>", html, re.IGNORECASE | re.DOTALL)
    if match is None:
        return ""
    return match.group(1)


def test_basic() -> None:
    html = "<html><head><title>Hello</title></head><body></body></html>"
    assert title_of(html) == "Hello"


def test_no_title() -> None:
    assert title_of("<html><body>No title here</body></html>") == ""


def test_empty_string() -> None:
    assert title_of("") == ""


def test_empty_title() -> None:
    assert title_of("<title></title>") == ""


def test_case_insensitive_tags() -> None:
    assert title_of("<HTML><HEAD><TITLE>Upper</TITLE></HEAD></HTML>") == "Upper"
    assert title_of("<Title>Mixed</tITLE>") == "Mixed"


def test_only_first_title_used() -> None:
    assert title_of("<title>One</title><title>Two</title>") == "One"


def test_unclosed_title() -> None:
    assert title_of("<html><title>Never closed<body>") == ""


def test_whitespace_preserved() -> None:
    assert title_of("<title>  spaced out \n</title>") == "  spaced out \n"


def test_multiline_title() -> None:
    assert title_of("<title>Line one\nLine two</title>") == "Line one\nLine two"


def test_title_with_other_content_around() -> None:
    html = "<!doctype html>\n<meta charset='utf-8'>\n<title>Page & Co</title>\n<p>x</p>"
    assert title_of(html) == "Page & Co"


@pytest.mark.parametrize(
    ("html", "expected"),
    [
        ("<title>a</title>", "a"),
        ("x<title>b</title>y", "b"),
        ("</title><title>c</title>", "c"),
        ("<title>", ""),
    ],
)
def test_parametrized(html: str, expected: str) -> None:
    assert title_of(html) == expected
